"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[32943],{17213(e,t,s){s.r(t),s.d(t,{assets:()=>c,contentTitle:()=>n,default:()=>u,frontMatter:()=>i,metadata:()=>o,toc:()=>p});const o=JSON.parse('{"id":"general/new-jumpcloud-report-users-to-sso-applications","title":"New Jumpcloud Report Users To Sso Applications","description":"By dwjohn","source":"@site/docs/general/new-jumpcloud-report-users-to-sso-applications.md","sourceDirName":"general","slug":"/general/new-jumpcloud-report-users-to-sso-applications","permalink":"/jc-community-archive/general/new-jumpcloud-report-users-to-sso-applications","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"New Jumpcloud Report Users To Sso Applications","description":"By dwjohn"},"sidebar":"docs","previous":{"title":"New Jumpcloud Report Os Patch Management Policy Status","permalink":"/jc-community-archive/general/new-jumpcloud-report-os-patch-management-policy-status"},"next":{"title":"New Jumpcloud Report Users To User Groups","permalink":"/jc-community-archive/general/new-jumpcloud-report-users-to-user-groups"}}');var a=s(74848),r=s(28453);const i={title:"New Jumpcloud Report Users To Sso Applications",description:"By dwjohn"},n=void 0,c={},p=[];function l(e){const t={a:"a",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.p,{children:"Howdy JumpCloud Community! Back to talk about another new report that we have added to the JumpCloud Reports portfolio called Users to SSO Applications. At a high level, this report is meant to provide IT Administrators with a list of all users in an organization along with the SSO applications to which they have been given access.\xa0 Other valuable data like last login timestamp and user group information are also included in the report."}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Background:"})," As I stated in a previous post, we are continuing to invest in providing IT Administrators with easy access to valuable data that is on the JumpCloud platform. One of the more requested views coming from customers is to simply provide them with artifacts showing them which users have access to what resources (\u201cWho has access to what?\u201d). Our first set of reports (Users to Devices, Users to Directories, Users to LDAP, and Users to RADIUS Server) that we released also fell into this category. This is just the first step in providing these \u201cresource access\u201d views. Over time, we will start to explore a more interactive approach to show these types of relationships and give customers a more customizable way to pull this data."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Tasks to be done:"})," Based upon feedback from customers, we expect this report to be leveraged for multiple purposes including meeting compliance requirements, troubleshooting issues, and assessing policy compliance to name a few.\xa0"]}),"\n",(0,a.jsx)(t.p,{children:"A more tactical example is determining what users actually require access to an application. We often hear from IT Administrators that their users will request access to an application but may never use that application or will use an application for a period of time and then stop using it without telling the IT Administrator. In many cases, this results in unnecessary costs for the company. With \u201clast login timestamp\u201d being included as a field in this report, customers can see a user's usage and determine whether or not they actually need access to the application. This can result in real savings for customers."}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Users to SSO Applications details:"})," Administrators on the JumpCloud platform can access this report in the same manner as any other report. Simply navigate to the \u201cReports\u201d tab under the \u201cInsights\u201d section on the left navigation in the Admin Console. On this page, there is a dropdown selector that allows administrators to select the Users to SSO Applications report."]}),"\n",(0,a.jsx)(t.p,{children:"This report includes username, user email, association type, user group name, association timestamp, application name, last login timestamp, and associated object id\u2019s. This report is also going to provide which applications have no users and which users have no applications. One item of note is that the only way that a user can have access to an application on the JumpCloud platform is by being part of a user group. Individual users cannot be directly bound to an application without being part of a user group, thus all users with access to applications will have an \u201cindirect\u201d association type in the report."}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Wrap Up:"})," If you are looking for more information on JumpCloud Reports, check out our ",(0,a.jsx)(t.a,{href:"https://support.jumpcloud.com/s/article/JumpCloud-Reports",children:"JumpCloud Reports"})," knowledge base article and ",(0,a.jsx)(t.a,{href:"https://jumpcloud.com/blog/jumpcloud-reports-data-benefits",children:"Introducing JumpCloud Reports: It\u2019s More Than Just Data"})," blog post. Give the Users to SSO Applications report a try and share any details on how you are using it. We are always impressed by the creative ways that JumpCloud customers are using these reports."]})]})}function u(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},28453(e,t,s){s.d(t,{R:()=>i,x:()=>n});var o=s(96540);const a={},r=o.createContext(a);function i(e){const t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function n(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);